// @prometheus 0.2.0
"use client"

import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react"

import { cn } from "@/lib/utils"
import { SurfaceProvider, useSurface } from "@/lib/surface-context"
import { surfaceClasses } from "@/lib/surface-classes"
import {
  OVERLAY_CORNERS,
  cornersCssRadius,
  useCornerRef,
  type CornerSize,
  type SmoothCornerOptions,
} from "@/lib/smooth-corners"

export function useElevatedLevel(offset: number) {
  const substrate = useSurface()
  return Math.min(substrate + offset, 8)
}

interface ElevatedProps extends ComponentPropsWithoutRef<"div"> {
  /**
   * Steps above the current substrate.
   *
   * The panel's own level becomes `min(substrate + offset, 8)` and is
   * re-provided to descendants, so nested overlays keep climbing.
   *
   * Conventional offsets:
   * 2 — dropdown / popover / select menu / tooltip
   * 4 — dialog / modal / drawer / sheet
   */
  offset: number
  /**
   * Override for the shadow level. Defaults to the computed surface level.
   *
   * Pass a fixed value when the component should keep a constant shadow
   * regardless of depth — e.g. a dropdown always reads as shadow-surface-3
   * whether it opens on the page or inside a dialog.
   */
  shadowLevel?: number
  /**
   * Lisse smooth-corner config. Defaults to panel (`xl` / 16px, squircle, smoothing 1).
   * Pass a preset key (`"lg"`, `"xl"`, …) or a full `SmoothCornerOptions` object.
   */
  corners?: SmoothCornerOptions | CornerSize
  children?: ReactNode
}

const Elevated = forwardRef<HTMLDivElement, ElevatedProps>(
  (
    {
      offset,
      shadowLevel,
      corners = OVERLAY_CORNERS.panel,
      className,
      style,
      children,
      ...props
    },
    forwardedRef
  ) => {
    const level = useElevatedLevel(offset)
    const ref = useCornerRef(corners, forwardedRef)

    return (
      <SurfaceProvider value={level}>
        <div
          ref={ref}
          className={cn(surfaceClasses(level, shadowLevel ?? level), className)}
          {...props}
          style={{ borderRadius: cornersCssRadius(corners), ...style }}
        >
          {children}
        </div>
      </SurfaceProvider>
    )
  }
)
Elevated.displayName = "Elevated"

export { Elevated }
export type { ElevatedProps }

// @prometheus 0.2.0
"use client"

import { createContext, useContext, type ReactNode } from "react"

const SurfaceContext = createContext(1)

export function useSurface(): number {
  return useContext(SurfaceContext)
}

export function SurfaceProvider({
  value,
  children,
}: {
  value: number
  children: ReactNode
}) {
  return (
    <SurfaceContext.Provider value={Math.max(1, Math.min(8, value))}>
      {children}
    </SurfaceContext.Provider>
  )
}

// @prometheus 0.2.0
/**
 * Static lookup tables for surface tokens.
 *
 * Tailwind v4's scanner only generates utilities for literal class names.
 * Template strings like `bg-surface-${level}` never emit, so the background
 * renders transparent. Keep every level written out here.
 */

export const SURFACE_BG: Record<number, string> = {
  1: "bg-surface-1",
  2: "bg-surface-2",
  3: "bg-surface-3",
  4: "bg-surface-4",
  5: "bg-surface-5",
  6: "bg-surface-6",
  7: "bg-surface-7",
  8: "bg-surface-8",
}

export const SURFACE_SHADOW: Record<number, string> = {
  1: "shadow-surface-1",
  2: "shadow-surface-2",
  3: "shadow-surface-3",
  4: "shadow-surface-4",
  5: "shadow-surface-5",
  6: "shadow-surface-6",
  7: "shadow-surface-7",
  8: "shadow-surface-8",
}

export const SURFACE_HOVER_BG: Record<number, string> = {
  1: "hover:bg-surface-1",
  2: "hover:bg-surface-2",
  3: "hover:bg-surface-3",
  4: "hover:bg-surface-4",
  5: "hover:bg-surface-5",
  6: "hover:bg-surface-6",
  7: "hover:bg-surface-7",
  8: "hover:bg-surface-8",
}

export const SURFACE_HOVER_SHADOW: Record<number, string> = {
  1: "hover:shadow-surface-1",
  2: "hover:shadow-surface-2",
  3: "hover:shadow-surface-3",
  4: "hover:shadow-surface-4",
  5: "hover:shadow-surface-5",
  6: "hover:shadow-surface-6",
  7: "hover:shadow-surface-7",
  8: "hover:shadow-surface-8",
}

function clampLevel(level: number) {
  return Math.round(Math.max(1, Math.min(8, level)))
}

export function surfaceClasses(
  bgLevel: number,
  shadowLevel: number = bgLevel
): string {
  return `${SURFACE_BG[clampLevel(bgLevel)]} ${SURFACE_SHADOW[clampLevel(shadowLevel)]}`
}

export function surfaceHoverClasses(
  bgLevel: number,
  shadowLevel: number = bgLevel
): string {
  return `${SURFACE_HOVER_BG[clampLevel(bgLevel)]} ${SURFACE_HOVER_SHADOW[clampLevel(shadowLevel)]}`
}

/** Conventional lift above the current substrate. */
export const SURFACE_OFFSET = {
  menu: 2,
  tooltip: 2,
  dialog: 4,
} as const

/** Fixed shadow weight so a menu still reads as a menu inside a dialog. */
export const SURFACE_SHADOW_LEVEL = {
  menu: 3,
  tooltip: 3,
  dialog: 5,
} as const
